"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";

export default function LoadingScreen() {
  const [isVisible, setIsVisible] = useState(true);
  const finishedRef = useRef(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  const completeLoading = useCallback(() => {
    if (finishedRef.current) return;
    finishedRef.current = true;
    setIsVisible(false);
    window.dispatchEvent(new Event("loading-complete"));
    (window as any).__loadingComplete = true;
  }, []);

  useEffect(() => {
    // Attempt playback immediately
    if (videoRef.current) {
      videoRef.current.play().catch(() => {
        // Autoplay policy fallback (e.g. if muted restriction or power saving)
      });
    }

    // Safety fallback: ensure screen transitions even if video takes time to load/stall
    const fallbackTimer = setTimeout(() => {
      completeLoading();
    }, 3200);

    return () => clearTimeout(fallbackTimer);
  }, [completeLoading]);

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 1 }}
          exit={{ 
            opacity: 0, 
            scale: 1.05, 
            filter: "blur(12px)" 
          }}
          transition={{ ease: [0.33, 1, 0.68, 1], duration: 0.7 }}
          onClick={completeLoading}
          className="fixed inset-0 z-[9999] flex items-center justify-center bg-black select-none pointer-events-auto overflow-hidden cursor-pointer"
        >
          <video
            ref={videoRef}
            autoPlay
            muted
            playsInline
            preload="auto"
            onEnded={completeLoading}
            className="w-full h-full object-cover"
          >
            <source src="/videos/match-cut.webm" type="video/webm" />
            <source src="/videos/match-cut.mp4" type="video/mp4" />
          </video>

          {/* Subtle click-to-skip button */}
          <div className="absolute bottom-6 right-6 z-10 px-3 py-1.5 rounded-full bg-black/40 border border-white/10 backdrop-blur-md text-[11px] font-medium tracking-wider uppercase text-neutral-300 opacity-60 hover:opacity-100 transition-opacity">
            Click to skip
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
